// Проверки формата показа адреса с Unit (#b2f74544). Только просмотр: ничего не сохраняют, JobDetail не открывают (автосохранение).
// Сессия и язык — из address-helpers.ts (ADMIN_STATE, setEnglish); этот файл их не меняет.
import { expect, Locator, Page } from '@playwright/test';

/** Клиент «test» (компания «test»): адрес «2221 NW Federal Hwy, Unit 3123, Stuart, FL 34994, USA». */
export const TEST_CLIENT_ID = 'ff72d05d-ea39-4744-a1db-95f952bde720';
/** Клиент «QA-unit client»: адрес «2221 Northwest Federal Highway, Apt 5B, Stuart, Florida». */
export const QA_UNIT_CLIENT_ID = 'fea68c2f-bf63-4a33-a613-8f7150d37684';

/** Часть адреса «квартира»: Unit 12 / Apt 5B / Suite 3300 / Ste 200 / #12. */
const UNIT_PART = /^(?:(?:Unit|Apt|Suite|Ste)\s+[\w-]+|#[\w-]+)$/i;

/** Адрес клиента «test» в целевом формате (номер Unit не фиксируем — данные могут меняться). */
export const TEST_CLIENT_ADDRESS = /2221 NW Federal Hwy, Unit [\w-]+, Stuart, FL 34994, USA/;

/**
 * Нет ни одного признака старого/сломанного формата в тексте области:
 * Unit после страны, «Unit» перед типом (Unit Apt / Unit #), пустой Unit, двойная запятая.
 */
export function expectNoBrokenUnitFormat(text: string, where: string) {
  expect(text, `${where}: Unit после страны («USA, Unit …»)`).not.toMatch(/\bUSA\s*,\s*(?:Unit|Apt|Suite|Ste|#)/i);
  expect(text, `${where}: «Unit» перед типом (Unit Apt / Unit Suite / Unit #)`).not.toMatch(/\bUnit\s+(?:Unit|Apt|Suite|Ste|#)/i);
  expect(text, `${where}: пустой Unit («Unit,»)`).not.toMatch(/\bUnit\s*,/);
  expect(text, `${where}: двойная запятая («, ,»)`).not.toMatch(/,\s*,/);
}

/** Адрес с квартирой: квартира — вторая часть, сразу после улицы. */
export function expectUnitRightAfterStreet(address: string, where: string) {
  const parts = address.split(',').map((s) => s.trim());
  expect(parts.length, `${where}: адрес «${address}» — мало частей`).toBeGreaterThanOrEqual(3);
  expect(parts[1], `${where}: в «${address}» сразу после улицы должна идти квартира`).toMatch(UNIT_PART);
  expect(parts.slice(2).some((p) => UNIT_PART.test(p)), `${where}: в «${address}» квартира повторяется дальше`).toBe(false);
}

/** Найти в тексте адрес, начинающийся с улицы, — до конца строки. */
export function pickAddress(text: string, street: string): string {
  const line = text.split('\n').map((l) => l.trim()).find((l) => l.includes(street)) ?? '';
  return line.slice(line.indexOf(street));
}

/** Текст области (innerText), когда в ней уже есть ожидаемое. */
export async function textOf(area: Locator, mustContain: string | RegExp): Promise<string> {
  await expect(area).toContainText(mustContain);
  return area.innerText();
}

/** Страница клиента → вкладка Jobs (только просмотр). */
export async function openCustomerJobs(page: Page, customerId: string, firstJob: string) {
  await page.goto(`/CustomerDetail?id=${customerId}`);
  const tab = page.getByRole('tab', { name: /^Jobs/ }).first();
  await expect(tab).toBeVisible();
  await tab.click();
  await expect(page.locator('main')).toContainText(firstJob);
}

/**
 * Текст самой маленькой видимой записи в main, где есть номер работы и адрес (строка таблицы / карточка).
 * Нужен, чтобы адрес проверялся у конкретной работы, а не где-то на странице.
 */
export async function jobEntryText(page: Page, jobId: string, street: string): Promise<string> {
  let found = '';
  await expect
    .poll(async () => {
      found = await page.locator('main').evaluate(
        (main, [j, s]) => {
          const els = [...main.querySelectorAll<HTMLElement>('*')].filter(
            (e) => e.offsetParent !== null && e.innerText.includes(j) && e.innerText.includes(s),
          );
          const min = els.filter((e) => !els.some((o) => o !== e && e.contains(o)));
          return min[0]?.innerText ?? '';
        },
        [jobId, street] as [string, string],
      );
      return found;
    }, { message: `запись ${jobId} с адресом «${street}…»` })
    .not.toBe('');
  return found;
}
